import { describe, it, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { openDatabase } from './db.js';
import { reserve } from './bookings.js';
import { NOT_FOUND, TABLE_TOO_SMALL, SLOT_TAKEN, BAD_REQUEST } from './errors.js';

const RESTAURANT_ID = 1;
const ZONE = 'Asia/Bangkok';

describe('retry budget', () => {
  let dir: string;
  let db: any;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'tk2-retry-'));
    db = openDatabase(join(dir, 'tablekeeper.db'), { createIfMissing: true });
    // minimal fixture
    db.run(`
      INSERT INTO restaurants (id, name, timezone) VALUES (${RESTAURANT_ID}, 'R', '${ZONE}');
      INSERT INTO tables (id, restaurant_id, seats) VALUES (1, ${RESTAURANT_ID}, 4);
    `);
  });

  afterEach(() => {
    db.close();
    rmSync(dir, { recursive: true, force: true });
  });

  it('produces a refusal after exhausting retry budget under contention', (t) => {
    // create an initial booking to contend
    const res1 = reserve(RESTAURANT_ID, 2026, 7, 1, 18, 0, 60, 'k1', 1);
    assert.equal(res1.ok, true);
    // contend with new key
    const res2 = reserve(RESTAURANT_ID, 2026, 7, 1, 18, 0, 60, 'k2', 1);
    assert.equal(res2.ok, false);
    assert.ok(res2.code === SLOT_TAKEN || res2.code === TABLE_TOO_SMALL || res2.code === BAD_REQUEST || res2.code === NOT_FOUND);
  });
});
