import { timingSafeEqual } from 'node:crypto';

export const UNAUTHORIZED_STATUS = 401;

export type AuthErrorEnvelope = {
  status: number;
  body: { error: { code: 'UNAUTHORIZED'; message: string; details: Record<string, unknown> } };
};

export class AuthError extends Error {
  readonly code = 'UNAUTHORIZED' as const;
  readonly details: Record<string, unknown>;
  constructor(message: string, details: Record<string, unknown> = {}) {
    super(message);
    this.name = 'AuthError';
    this.details = details;
  }
  get status(): number { return UNAUTHORIZED_STATUS; }
  toEnvelope(): AuthErrorEnvelope {
    return { status: this.status, body: { error: { code: this.code, message: this.message, details: this.details } } };
  }
}

function constantTimeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  // Compare via a fixed-size digest so unequal lengths do not throw and do not
  // short-circuit; length is folded into the comparison rather than leaked.
  const ah = createHash('sha256').update(ab).digest();
  const bh = createHash('sha256').update(bb).digest();
  return timingSafeEqual(ah, bh);
}
