/**
 * API-key authentication for stage 3.
 *
 * The envelope is stage-1's, verbatim: `{ error: { code, message, details } }`, wrapped in
 * `{ status, body }` by `toEnvelope()` exactly as `ApiError` does. Stage 1's taxonomy has no
 * 401 code, so the code `UNAUTHORIZED` is defined here rather than added to a frozen module:
 * the shape is reused, the frozen file is not touched.
 */
import { createHash, timingSafeEqual } from 'node:crypto';

export const UNAUTHORIZED_STATUS = 401;
export const UNAUTHORIZED_CODE = 'UNAUTHORIZED';

export type AuthErrorDetails = Record<string, unknown>;

export type AuthEnvelope = {
  status: number;
  body: { error: { code: typeof UNAUTHORIZED_CODE; message: string; details: AuthErrorDetails } };
};

export class AuthError extends Error {
  readonly code = UNAUTHORIZED_CODE;
  readonly details: AuthErrorDetails;

  constructor(message: string, details: AuthErrorDetails = {}) {
    super(message);
    this.name = 'AuthError';
    this.details = details;
  }

  get status(): number {
    return UNAUTHORIZED_STATUS;
  }

  toEnvelope(): AuthEnvelope {
    return {
      status: this.status,
      body: { error: { code: this.code, message: this.message, details: this.details } },
    };
  }
}

export function isAuthError(value: unknown): value is AuthError {
  return value instanceof AuthError;
}

/**
 * Compare two candidate keys without leaking their length or a match position.
 *
 * Hashing both sides to a fixed-width digest means `timingSafeEqual` never sees
 * different-length buffers (it throws on those) and never returns early. The comparison
 * still visits every configured key, so a caller cannot learn which key matched by timing.
 */
function constantTimeEqual(a: string, b: string): boolean {
  const ah = createHash('sha256').update(a, 'utf8').digest();
  const bh = createHash('sha256').update(b, 'utf8').digest();
  return timingSafeEqual(ah, bh);
}

export function validateApiKey(candidate: unknown, keys: readonly string[]): boolean {
  if (typeof candidate !== 'string' || candidate.length === 0) return false;
  if (!Array.isArray(keys) || keys.length === 0) return false;
  let matched = false;
  for (const key of keys) {
    if (typeof key !== 'string' || key.length === 0) continue;
    if (constantTimeEqual(candidate, key)) matched = true;
  }
  return matched;
}

export type HeaderValue = string | string[] | undefined;
export type HeaderMap = Record<string, HeaderValue>;

export type RequireApiKeyConfig = {
  /** Accepted keys. Empty means every request is refused; there is no "auth disabled". */
  keys: readonly string[];
  /** Header carrying `Bearer <key>`. Defaults to `authorization`. */
  authorizationHeader?: string;
  /** Direct key header, used when the authorization header is absent. Defaults to `x-api-key`. */
  apiKeyHeader?: string;
};

const BEARER = /^Bearer[ \t]+(.+)$/i;

function readHeader(headers: HeaderMap, name: string): string | undefined {
  const wanted = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() !== wanted) continue;
    return Array.isArray(value) ? value[0] : value;
  }
  return undefined;
}

function extractCandidate(headers: HeaderMap, config: RequireApiKeyConfig): string | undefined {
  const authName = config.authorizationHeader ?? 'authorization';
  const directName = config.apiKeyHeader ?? 'x-api-key';
  const auth = readHeader(headers, authName);
  if (auth !== undefined) {
    const match = BEARER.exec(auth.trim());
    if (match !== null) return match[1].trim();
  }
  const direct = readHeader(headers, directName);
  if (direct !== undefined) {
    const trimmed = direct.trim();
    if (trimmed.length > 0) return trimmed;
  }
  return undefined;
}

/**
 * Return the validated key, or throw an `AuthError` whose envelope is a 401.
 *
 * A missing key and a wrong key are the same status and the same generic message; the
 * `details.reason` distinguishes them for logs without telling an attacker which guess was
 * closer. `details` never carries the presented key.
 */
export function requireApiKey(headers: HeaderMap, config: RequireApiKeyConfig): string {
  const candidate = extractCandidate(headers, config);
  if (candidate === undefined) {
    throw new AuthError('an API key is required', { reason: 'missing' });
  }
  if (!validateApiKey(candidate, config.keys)) {
    throw new AuthError('the API key is not valid', { reason: 'invalid' });
  }
  return candidate;
}
