```ts
import { type Db } from '../../stage-1/src/db.ts';

export type Migration = { name: string; up: (db: Db) => void };

const LEDGER = 'schema_migration';

function ensureLedger(db: Db): void {
  db.exec(`CREATE TABLE IF NOT EXISTS ${LEDGER} (name TEXT PRIMARY KEY, applied_at_utc TEXT NOT NULL)`);
}

function applied(db: Db): Set<string> {
  ensureLedger(db);
  const rows = db.prepare(`SELECT name FROM ${LEDGER}`).all() as { name: string }[];
  return new Set(rows.map(r => r.name));
}

export function currentVersion(db: Db): string | null {
  const names = [...applied(db)];
  if (names.length === 0) return null;
  return names.sort().at(-1) ?? null;
}

export function runMigrations(db: Db, migrations: readonly Migration[]): string[] {
  // validate names unique + non-empty
  const seen = new Set<string>();
  for (const m of migrations) {
    if (typeof m.name !== 'string' || m.name.length === 0) throw new TypeError(...);
    if (seen.has(m.name)) throw new TypeError(`duplicate migration name ${m.name}`);
    seen.add(m.name);
    if (typeof m.up !== 'function') throw new TypeError(...);
  }
  const done = applied(db);
  const appliedNow: string[] = [];
  for (const migration of migrations) {
    if (done.has(migration.name)) continue;
    db.exec('BEGIN IMMEDIATE');
    try {
      migration.up(db);
      db.prepare(`INSERT INTO ${LEDGER} (name, applied_at_utc) VALUES (?, ?)`).run(migration.name, new Date().toISOString());
      db.exec('COMMIT');
    } catch (err) {
      rollback; throw err;
    }
    done.add(migration.name);
    appliedNow.push(migration.name);
  }
  return appliedNow;
}
```

